import { memo, useState } from "react";
import { Icon, Link, Stack, Text } from "@kit/index.js";
import { Translate, useTrack, withTracking } from "travel-platform";
import styles from "./Header.module.css";

const TrackedLink = withTracking(Link, "header.menu_link");

const MORE = [
    ["globe", "header.more_cruises"], ["car", "header.more_rental"], ["airport", "header.more_lounges"], ["building", "header.more_business"], ["landmark", "header.more_guides"], ["calendar", "header.more_events"],
    ["map", "header.more_maps"], ["sparkle", "header.more_deals"], ["leaf", "header.more_sustainable"], ["question", "header.more_help"], ["person", "header.more_groups"], ["hotel", "header.more_long_stays"],
];
const ACCOUNT = ["header.account_bookings", "header.account_lists", "header.account_reviews", "header.account_rewards", "header.account_settings"];

const MenuItem = memo(function MenuItem({ icon, label, href }) {
    return (
        <li className={styles.menuItem}>
            <TrackedLink href={href} className={styles.menuLink} trackingData={{ href }}>
                {icon ? <Icon name={icon} size="small" /> : null}
                <Translate id={label} />
            </TrackedLink>
        </li>
    );
});

// The header's menus are rendered with the page and shown on demand.
export function HeaderMenus() {
    const track = useTrack();
    const [open, setOpen] = useState(null);
    return (
        <div className={styles.menus}>
            <button type="button" className={styles.menuToggle} aria-expanded={open === "more"} onClick={() => { track("header.more_open"); setOpen(open === "more" ? null : "more"); }}>
                <Translate id="header.more" />
            </button>
            <Stack as="nav" gap={2} className={open === "more" ? styles.menuOpen : styles.menu} aria-label="More products">
                <Text variant="strong_2"><Translate id="header.more_title" /></Text>
                <ul className={styles.menuList}>{MORE.map(([icon, key]) => <MenuItem key={key} icon={icon} label={key} href={`products/${key.slice(12)}.html`} />)}</ul>
            </Stack>
            <Stack as="nav" gap={2} className={open === "account" ? styles.menuOpen : styles.menu} aria-label="Account">
                <ul className={styles.menuList}>{ACCOUNT.map((key) => <MenuItem key={key} label={key} href={`account/${key.slice(15)}.html`} />)}</ul>
            </Stack>
        </div>
    );
}
