import { Button, Inline, Link, Tabs, Text } from "@kit/index.js";
import { TrackingScope, Translate, useTrack, useTranslation } from "travel-platform";
import "./catalog.js";
import { Logo } from "./Logo.jsx";
import { HeaderButton } from "./HeaderButton.jsx";
import { HeaderMenus } from "./HeaderMenus.jsx";
import styles from "./Header.module.css";

const NAV = [
    ["stays", "nav.stays", "hotel", "./"],
    ["flights", "nav.flights", "airport", "flights/"],
    ["packages", "nav.packages", "globe", "packages/"],
    ["cars", "nav.cars", "car", "cars/"],
    ["attractions", "nav.attractions", "landmark", "attractions/"],
    ["taxis", "nav.taxis", "car", "taxi/"],
];

function HeaderActions() {
    const t = useTranslation();
    const track = useTrack();
    return (
        <Inline gap={1} className={styles.actions}>
            <HeaderButton label={t("header.currency")} onClick={() => track("header.currency_open")}><Text as="span" variant="strong_2">EUR</Text></HeaderButton>
            <HeaderButton label={t("header.language")} icon="globe" onClick={() => track("header.language_open")} />
            <HeaderButton label={t("header.help")} icon="question" onClick={() => track("header.help_open")} />
            <Link href="partners/join.html" className={styles.listProperty}><Translate id="header.list_property" /></Link>
            <Button variant="light-outline" size="medium" href="account/register.html"><Translate id="header.register" /></Button>
            <Button variant="light-outline" size="medium" href="account/sign-in.html" data-testid="header-sign-in"><Translate id="header.sign_in" /></Button>
        </Inline>
    );
}

export default function Header({ product = "stays" }) {
    const t = useTranslation();
    const items = NAV.map(([id, key, icon, href]) => ({ id, label: t(key), icon, href }));
    return (
        <TrackingScope surface="header">
            <a href="#main" className={styles.skip}><Translate id="header.skip" /></a>
            <header className={styles.header} data-testid="header">
                <div className={styles.inner}>
                    <div className={styles.top}>
                        <Logo label={t("header.home")} />
                        <HeaderActions />
                    </div>
                    <Tabs items={items} selected={product} label={t("header.nav")} />
                    <HeaderMenus />
                </div>
            </header>
        </TrackingScope>
    );
}
